import {useState} from "react";import SectionHeader from "../../common/ui/SectionHeader/SectionHeader";import Input from "../../common/ui/Input/Input";import Button from "../../common/ui/Button/Button";import toast from "react-hot-toast";import VendorProfileService from "../../../services/VendorProfileService";
export default function SecuritySettings(){const [currentPassword,setCurrentPassword]=useState("");const [newPassword,setNewPassword]=useState("");const [confirmPassword,setConfirmPassword]=useState("");const [saving,setSaving]=useState(false);
async function save(){if(newPassword!==confirmPassword){toast.error("Passwords do not match.");return;}if(!/^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)(?=.*[^A-Za-z0-9]).{8,}$/.test(newPassword)){toast.error("Password must be at least 8 characters and include uppercase, lowercase, number and special character.");return;}try{setSaving(true);await VendorProfileService.changePassword(currentPassword,newPassword);toast.success("Password changed. Please sign in again.");window.dispatchEvent(new Event("eventnest-auth-expired"));setCurrentPassword("");setNewPassword("");setConfirmPassword("");}catch(e:any){toast.error(e.response?.data?.message||"Unable to change password.");}finally{setSaving(false);}}
return <><SectionHeader title="Security" subtitle="Update your account password."/><div className="settings-form"><Input name="currentPassword" label="Current Password" type="password" value={currentPassword} onChange={e=>setCurrentPassword(e.target.value)}/><Input name="newPassword" label="New Password" type="password" value={newPassword} onChange={e=>setNewPassword(e.target.value)}/><Input name="confirmPassword" label="Confirm Password" type="password" value={confirmPassword} onChange={e=>setConfirmPassword(e.target.value)}/><div className="password-guidelines"><h3>Password Requirements</h3><ul><li>Minimum 8 characters</li><li>At least one uppercase letter</li><li>At least one lowercase letter</li><li>At least one number</li><li>At least one special character</li></ul></div><div className="two-factor-card"><h3>Two-Factor Authentication</h3><p>Coming soon. Enable an extra layer of security for your account.</p></div><div className="settings-actions"><Button onClick={save}>{saving?"Updating...":"Change Password"}</Button></div></div></>}
